llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C59"],
      "claim": "KNI-272, a structurally related peptidomimetic HIV protease inhibitor sharing the hydroxyethylamine core and tert-butyl amide, had absolute oral bioavailability of 36.40% when given as a capsule post-prandially in patients, directly supporting F ≥20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "KNI-272 at 10 mg/kg in fasting patients had absolute oral bioavailability of 54.97 ± 19.78%, demonstrating that this chemotype can achieve well-absorbed oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "KNI-272 capsule bioavailability ranged from approximately 22% to 55% and was not appreciably different between fasting and post-prandial states, indicating robust F above the 20% threshold across feeding conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Indinavir, another HIV protease inhibitor with a tert-butyl carboxamide and hydroxyethylamine-like core, had systemic bioavailability of 0.60 (0.54–0.66) in humans, supporting moderate-to-good oral bioavailability for this inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Boceprevir, a peptidomimetic protease inhibitor with a tert-butyl carbamoyl group, had human oral bioavailability of approximately 20%, providing additional class-level support for reaching the F ≥20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In children, KNI-272 mean absolute bioavailability was 12% (range 3.5–25%), a contradictory pediatric data point; however, adult and post-prandial data are higher, and pediatric physiology may reduce absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥20%) because the closest analog KNI-272 shows adult absolute oral bioavailability of ~30–55%, including 36.4% post-prandially, and other peptidomimetic protease inhibitors such as indinavir and boceprevir support moderate-to-good oral absorption. Low-F analogs are structurally less transferable, and the pediatric low value for KNI-272 is outweighed by adult fed-state evidence.",
  "evidence_gaps": [
    "No direct bioavailability measurement exists for the query molecule; all evidence comes from analogs with low Morgan similarity (0.21–0.28).",
    "Fed-state data are available only for KNI-272, not for the query itself; food effects may differ with the decahydroisoquinoline and S-benzyl substituents.",
    "The pediatric low F for KNI-272 raises uncertainty about population-specific absorption, and the target population for the query is not specified.",
    "No explicit solubility, permeability, or first-pass metabolism data are available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

